WITH matched AS (SELECT s.*, sub.id AS subscription_id, sub.plan, sub.monthly_fee FROM orders s INNER JOIN subscriptions sub ON s.customer_id = sub.customer_id AND s.order_date BETWEEN sub.start_date AND sub.end_date) SELECT CASE WHEN subscription_id >= 10 THEN 'LARGE' ELSE 'SMALL' END AS subscription_id_tier, CASE WHEN amount >= 1350 THEN 'HIGH' ELSE 'LOW' END AS amount_tier, CORR(shipping_fee, discount) AS corr_shipping_fee_discount, COUNT(DISTINCT customer_id) AS distinct_customer_ids, SORT_ARRAY(COLLECT_SET(plan)) AS plan_list, APPROX_PERCENTILE(discount, ARRAY(0.25, 0.5, 0.75)) AS discount_quartiles, DENSE_RANK() OVER (PARTITION BY CASE WHEN subscription_id >= 10 THEN 'LARGE' ELSE 'SMALL' END ORDER BY COUNT(DISTINCT customer_id) DESC) AS distinct_customer_ids_dense_rank FROM matched GROUP BY CASE WHEN subscription_id >= 10 THEN 'LARGE' ELSE 'SMALL' END, CASE WHEN amount >= 1350 THEN 'HIGH' ELSE 'LOW' END
